import json
from archive.hollin import *
from archive.hollin import _file_checksum
class T:
    def __init__(s, drop=None): s.log=[]; s.parts={}; s.drop=drop; s.k=0
    def now(s): return 1000.0
    def send(s,m,p,h,b):
        s.log.append((m,p,h,b if not isinstance(b,bytes) else len(b)))
        R=lambda st,o: Response(st,{},json.dumps(o).encode())
        if m=='POST' and p=='/v3/uploads': return R(201,{'upload_id':'up_1','chunk_size':b['chunk_size'],'expires_at':99999})
        if m=='PUT': s.k+=1; s.parts[p]='"e%d"'%s.k; return R(200,{'part':1,'size':1,'etag':s.parts[p]})
        if p.endswith('commit'):
            if s.drop and not getattr(s,'d',0):
                s.d=1; s.parts.pop(s.drop); return R(409,{'error':{'code':'parts_missing','missing':[int(s.drop.split('/')[-1])]}})
            return R(201,{'file_id':'f','name':'n','size':1,'checksum':'c'})
t=T('/v3/uploads/up_1/parts/2')
print(upload_file(t,'n',b'x'*(70*1024),'pro',record=print))
for l in t.log: print(l)
print(_file_checksum([b'Hollin example part one, ',b'and part two.']))
print(_file_checksum([]))
EOF
